export const ROOF_EXPEDITION_ID='last-signal-roof-02';
export const ROOF_SURFACE=Object.freeze({version:1,elevation:160,platforms:Object.freeze([Object.freeze({x:750,y:680,w:560,h:460}),Object.freeze({x:1460,y:680,w:560,h:460}),Object.freeze({x:1270,y:850,w:230,h:100})])});
const cache=new WeakMap(),inside=(r,x,y)=>x>=r.x&&x<=r.x+r.w&&y>=r.y&&y<=r.y+r.h;
function subtract(intervals,low,high){return intervals.flatMap(([a,b])=>high<=a||low>=b?[[a,b]]:[[a,Math.max(a,low)],[Math.min(b,high),b]].filter(([x,y])=>y-x>1e-8));}
export function roofBoundary(surface=ROOF_SURFACE){if(cache.has(surface))return cache.get(surface);const edges=[];for(const r of surface.platforms)for(const [axis,fixed,low,high,sign]of [['x',r.x,r.y,r.y+r.h,-1],['x',r.x+r.w,r.y,r.y+r.h,1],['y',r.y,r.x,r.x+r.w,-1],['y',r.y+r.h,r.x,r.x+r.w,1]]){let spans=[[low,high]];for(const other of surface.platforms)if(other!==r){const probe=fixed+sign*1e-5,covered=axis==='x'?probe>other.x&&probe<other.x+other.w:probe>other.y&&probe<other.y+other.h;if(covered)spans=subtract(spans,axis==='x'?other.y:other.x,axis==='x'?other.y+other.h:other.x+other.w);}for(const[a,b]of spans)edges.push(axis==='x'?{a:{x:fixed,y:a},b:{x:fixed,y:b}}:{a:{x:a,y:fixed},b:{x:b,y:fixed}});}const result=Object.freeze(edges.map(e=>Object.freeze({a:Object.freeze(e.a),b:Object.freeze(e.b)})));cache.set(surface,result);return result;}
const sq=(x,y)=>x*x+y*y;
function pointDistance(p,a,b){const dx=b.x-a.x,dy=b.y-a.y,n=dx*dx+dy*dy,t=n?Math.max(0,Math.min(1,((p.x-a.x)*dx+(p.y-a.y)*dy)/n)):0;return sq(p.x-a.x-dx*t,p.y-a.y-dy*t);}
function cross(a,b,c){return (b.x-a.x)*(c.y-a.y)-(b.y-a.y)*(c.x-a.x);}
function segmentDistance(a,b,c,d){const abC=cross(a,b,c),abD=cross(a,b,d),cdA=cross(c,d,a),cdB=cross(c,d,b);if(abC*abD<0&&cdA*cdB<0)return 0;return Math.min(pointDistance(a,c,d),pointDistance(b,c,d),pointDistance(c,a,b),pointDistance(d,a,b));}
export function roofSupports(world,x,y,r=0){const s=world?.rooftop;if(!s)return true;if(s.platforms.some(q=>x>=q.x+r&&x<=q.x+q.w-r&&y>=q.y+r&&y<=q.y+q.h-r))return true;if(!s.platforms.some(rect=>inside(rect,x,y)))return false;const p={x,y},r2=Math.max(0,r)**2;return roofBoundary(s).every(edge=>pointDistance(p,edge.a,edge.b)+1e-8>=r2);}
export function roofSegmentSupports(world,a,b,r=0){if(!world?.rooftop)return true;if(world.rooftop.platforms.some(q=>[a,b].every(p=>p.x>=q.x+r&&p.x<=q.x+q.w-r&&p.y>=q.y+r&&p.y<=q.y+q.h-r)))return true;if(!roofSupports(world,a.x,a.y,r)||!roofSupports(world,b.x,b.y,r))return false;const clearance=Math.max(1e-6,r)**2;return roofBoundary(world.rooftop).every(edge=>segmentDistance(a,b,edge.a,edge.b)+(r>0?1e-8:0)>=clearance);}
export function validRoofSurface(s){return !!s&&Object.keys(s).length===3&&s.version===ROOF_SURFACE.version&&s.elevation===ROOF_SURFACE.elevation&&Array.isArray(s.platforms)&&s.platforms.length===ROOF_SURFACE.platforms.length&&s.platforms.every((r,i)=>r&&Object.keys(r).length===4&&['x','y','w','h'].every(k=>r[k]===ROOF_SURFACE.platforms[i][k]));}
export function createRooftopWorld({nextId,seed}){const obstacles=[],decor=[],add=(x,y,w,h,kind,hp=Infinity,extra={})=>{const o={id:nextId(),x,y,w,h,kind,hp,maxHp:hp,destroyed:false,...extra};obstacles.push(o);return o;};
for(const {a,b}of roofBoundary()){const vertical=a.x===b.x,length=Math.hypot(b.x-a.x,b.y-a.y),count=Math.ceil(length/180);for(let i=0;i<count;i++){const t=i/count,dx=(b.x-a.x)/count,dy=(b.y-a.y)/count;add(a.x+(b.x-a.x)*t-(vertical?4:0),a.y+(b.y-a.y)*t-(vertical?0:4),vertical?8:dx,vertical?dy:8,'fence',Infinity,{height:42,variant:vertical?'vertical':'horizontal'});}}
add(930,840,100,80,'building',Infinity,{height:48,variant:'roof-generator',label:'POWER'});add(1700,850,70,70,'building',Infinity,{height:42,variant:'roof-relay',label:'RELAY'});add(1900,740,100,100,'building',Infinity,{height:65,variant:'roof-stairs',label:'STAIRS'});add(1110,760,30,30,'barrel',22,{height:25});add(1590,1000,30,30,'barrel',22,{height:25});
for(const [x,y]of [[800,730],[1240,1060],[1520,730],[1950,1060]])decor.push({x,y,kind:'lamp'});decor.push({x:1740,y:930,kind:'lamp',variant:'relay-speaker'});
return {width:2400,height:1800,seed,theme:'residential',obstacles,decor,roads:[],spawn:{x:1020,y:1030},exit:{x:1870,y:850,open:false},expeditionId:ROOF_EXPEDITION_ID,rooftop:ROOF_SURFACE};}
